<?php $heading=!empty($mode_perbaikan)?'Perbaiki Data & Berkas PBG':($row?'Ubah Pengajuan PBG':'Tambah Pengajuan PBG'); $top_actions=''; $this->load->view('pbg_pu/header',compact('heading','top_actions','nama_pengguna')); $v=function($k)use($row){return set_value($k,$row[$k]??'');}; ?>
<div class="card form-card"><a href="<?= base_url('pengajuan-pbg') ?>">← Kembali ke Pengajuan PBG</a><?= validation_errors('<div class="notice" style="background:#fce0e0">','</div>') ?><?php foreach($errors as $e):?><div class="notice" style="background:#fce0e0"><?= $e ?></div><?php endforeach;?>
<?= form_open_multipart(current_url()) ?><h2 class="section-title">Data Pemohon</h2><div class="grid"><div><label>Nama Pemohon</label><input name="nama_pemohon" value="<?= htmlspecialchars($v('nama_pemohon')) ?>" required></div><div><label>NIK</label><input name="nik" maxlength="20" value="<?= htmlspecialchars($v('nik')) ?>"></div><div><label>Nomor HP</label><input name="no_hp" value="<?= htmlspecialchars($v('no_hp')) ?>" required></div><div><label>Email</label><input type="email" name="email" value="<?= htmlspecialchars($v('email')) ?>"></div></div>
<h2 class="section-title">Data Bangunan</h2><div class="grid"><div class="full"><label>Alamat Bangunan</label><input name="alamat_bangunan" value="<?= htmlspecialchars($v('alamat_bangunan')) ?>" required></div><div><label>Jenis Bangunan</label><input name="jenis_bangunan" value="<?= htmlspecialchars($v('jenis_bangunan')) ?>" required></div><div><label>Kategori</label><select name="kategori_bangunan"><?php foreach(array('sederhana'=>'Sederhana','tidak_sederhana'=>'Tidak Sederhana','perumahan'=>'Perumahan') as $k=>$l):?><option value="<?= $k ?>" <?= $v('kategori_bangunan')===$k?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></div><div><label>Luas Bangunan (m²)</label><input type="number" step=".01" name="luas_bangunan" value="<?= htmlspecialchars($v('luas_bangunan')) ?>"></div><div class="full"><label>Keterangan</label><textarea name="keterangan"><?= htmlspecialchars($v('keterangan')) ?></textarea></div></div>
<h2 class="section-title">Dokumen Persyaratan</h2><div class="grid"><?php foreach($files as $field=>$label):?><div class="upload"><label><?= htmlspecialchars($label) ?></label><?php if($row&&!empty($row[$field])):?><small>Berkas sudah tersedia; unggah hanya untuk mengganti.</small><?php endif;?><input type="file" name="<?= $field ?>" accept=".jpg,.jpeg,.png,.pdf"></div><?php endforeach;?></div><?php if(!empty($mode_perbaikan)):?><div style="margin-top:24px"><label>Catatan Perbaikan</label><textarea name="catatan_perbaikan" required placeholder="Jelaskan data atau berkas yang telah diperbaiki."></textarea></div><?php endif;?><div style="margin-top:28px;display:flex;gap:10px"><button class="btn btn-primary"><?= !empty($mode_perbaikan)?'Kirim Perbaikan':'Simpan Pengajuan' ?></button><a class="btn" href="<?= $row?base_url('pengajuan-pbg/tahap/'.$row['id'].'/3'):base_url('pengajuan-pbg') ?>">Batal</a></div><?= form_close() ?></div>
